public sealed class PaymentGateway
{
    public async Task<PaymentResult?> ChargeAsync(ChargeRequest request)
    {
        // A new connection pool per call: a new TCP and TLS handshake,
        // and one more socket left in TIME_WAIT after disposal
        using var http = new HttpClient
        {
            BaseAddress = new Uri("https://payments.example.com")
        };
        var response = await http.PostAsJsonAsync("/charges", request);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PaymentResult>();
    }
}

var builder = WebApplication.CreateBuilder(args);
// Typed client: registered as transient, built on a pooled, rotated handler
builder.Services.AddHttpClient<PaymentGateway>(client =>
    client.BaseAddress = new Uri("https://payments.example.com"));
var app = builder.Build();

app.MapPost("/checkout", (ChargeRequest request, PaymentGateway gateway) =>
    gateway.ChargeAsync(request));
app.Run();

public sealed class PaymentGateway(HttpClient http)
{
    public async Task<PaymentResult?> ChargeAsync(ChargeRequest request)
    {
        var response = await http.PostAsJsonAsync("/charges", request);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<PaymentResult>();
    }
}

